pub mod kit_backbone {
    //! @emoji 🗄️ Dev JSON + local `.compose/` kit backbones: atomic single-file writes, multi-db SQLite + blobs dir, replay via [`kit_graph_engine::apply_semantic_op_json`].

    use std::path::{Path, PathBuf};
    use std::sync::Arc;

    use rusqlite::Connection;

    use crate::error::ComposeError;
    use crate::id::Id;
