        Self { id: Id::default(), owner_session: Weak::new(), the_kit: Arc::default(), alternatives: RwLock::new(Vec::new()), checkpoints: RwLock::new(Vec::new()), releases: RwLock::new(Vec::new()), drafts: RwLock::new(Vec::new()) }
    }
